11	// v2: alwaysArmed became the default. v1 prefs are migrated once without their alwaysArmed value.
12	const KEY = "mise.cook-prefs.v2";
13	const OLD_KEY = "mise.cook-prefs";
14	export const DEFAULT_PREFS: CookPrefs = { gesture: DEFAULT_GESTURE_CONFIG, showCamera: true, autoRead: false };
15	
16	export function loadPrefs(): CookPrefs {
17	  try {
18	    let saved = JSON.parse(localStorage.getItem(KEY) ?? "null") as Partial<CookPrefs> | null;
19	    if (!saved) {
20	      saved = JSON.parse(localStorage.getItem(OLD_KEY) ?? "null") as Partial<CookPrefs> | null;
21	      if (!saved) return DEFAULT_PREFS;
22	      if (saved.gesture) delete (saved.gesture as Partial<GestureConfig>).alwaysArmed; // take the new default
23	      localStorage.setItem(KEY, JSON.stringify(saved));
24	      localStorage.removeItem(OLD_KEY);
25	    }
26	    // Merge over defaults so new config fields added later still get values.
27	    return { ...DEFAULT_PREFS, ...saved, gesture: { ...DEFAULT_GESTURE_CONFIG, ...saved.gesture } };
28	  } catch {
29	    return DEFAULT_PREFS;
30	  }
31	}
32	
33	export function savePrefs(p: CookPrefs) {
34	  try {
35	    localStorage.setItem(KEY, JSON.stringify(p));
36	  } catch {}
37	}
